  const [onlineUsers,setOnlineUsers]=useState([]),[socket,setSocket]=useState(null),[typingUser,setTypingUser]=useState(false);
  useEffect(()=>{const socket=io(API_BASE,{auth:{token:auth?.token}});setSocket(socket);socket.on("connect",()=>setRealtime("online"));socket.on("disconnect",()=>setRealtime("offline"));socket.on("connect_error",()=>setRealtime("offline"));socket.on("message:new",m=>{setMessages(prev=>prev.some(x=>x._id===m._id)?prev:[...prev,m]);setConversations(prev=>prev.map(c=>c._id===m.conversation?{...c,lastMessage:m,updatedAt:m.createdAt}:c).sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)))});socket.on("notification:new",async()=>{try{const d=await apiFetch("/api/notifications",auth);setNotifications(d.notifications);setUnread(d.unread)}catch{}});socket.on("presence:list",d=>setOnlineUsers(d.userIds||[]));socket.on("presence:online",d=>setOnlineUsers(prev=>prev.includes(d.userId)?prev:[...prev,d.userId]));socket.on("presence:offline",d=>setOnlineUsers(prev=>prev.filter(id=>id!==d.userId)));socket.on("typing:start",d=>{if(activeConversationRef.current?._id===d.conversationId)setTypingUser(true)});socket.on("typing:stop",d=>{if(activeConversationRef.current?._id===d.conversationId)setTypingUser(false)});return()=>{setSocket(null);socket.disconnect()}},[auth?.token]);
  const [menuOpen,setMenuOpen]=useState(false);
  const [active,setActive]=useState("home"),[posts,setPosts]=useState([]),[me,setMe]=useState(auth.user),[discover,setDiscover]=useState([]),[query,setQuery]=useState(""),[searchResults,setSearchResults]=useState([]),[hashtag,setHashtag]=useState(""),[savedPosts,setSavedPosts]=useState([]),[loading,setLoading]=useState(true),[message,setMessage]=useState(""),[notifications,setNotifications]=useState([]),[unread,setUnread]=useState(0),[showNotifications,setShowNotifications]=useState(false);
  const navigateToSection = key => { setActive(key); setMenuOpen(false); window.scrollTo({ top: 0, behavior: "auto" }); };
  const load=async()=>{setLoading(true);setMessage("");try{const [postData,meData,users,notificationResponse]=await Promise.all([apiFetch("/api/posts",auth),apiFetch("/api/users/me",auth),apiFetch("/api/users/discover",auth),apiFetch("/api/notifications",auth)]);setPosts(postData);setMe(meData.user);setDiscover(users);setNotifications(notificationResponse.notifications);setUnread(notificationResponse.unread);const next={...auth,user:meData.user};setAuth(next);localStorage.setItem("shivasha_auth",JSON.stringify(next))}catch(e){setMessage(e.message)}finally{setLoading(false)}};
  useEffect(()=>{load()},[]);
  useEffect(()=>{const q=query.trim();if(q.length<2){setSearchResults([]);return}const t=setTimeout(async()=>{try{setSearchResults(await apiFetch("/api/users/search?q="+encodeURIComponent(q),auth))}catch{setSearchResults([])}},300);return()=>clearTimeout(t)},[query]);
  const visibleUsers=useMemo(()=>discover.filter(u=>(u.name+" "+(u.bio||"")).toLowerCase().includes(query.toLowerCase())),[discover,query]);
  const updatePost=p=>setPosts(prev=>prev.map(x=>x._id===p._id?p:x));
  const createPost=async(text,images)=>{try{const p=await apiFetch("/api/posts",auth,{method:"POST",body:JSON.stringify({text,images})});setPosts(prev=>[p,...prev]);setActive("home")}catch(e){setMessage(e.message)}};
