  const [viewUser,setViewUser]=useState(null),[connections,setConnections]=useState(null),[viewPost,setViewPost]=useState(null),[conversations,setConversations]=useState([]),[activeConversation,setActiveConversation]=useState(null),[messages,setMessages]=useState([]);
  const activeConversationRef=useRef(null);
