  const startConversation=async userId=>{try{const conversation=await apiFetch("/api/messages/conversations",auth,{method:"POST",body:JSON.stringify({userId})});await openMessages();await openConversation(conversation)}catch(e){setMessage(e.message)}};
  const sendMessage=async text=>{if(!activeConversation||!text.trim())return;try{const m=await apiFetch("/api/messages/conversations/"+activeConversation._id+"/messages",auth,{method:"POST",body:JSON.stringify({text:text.trim()})});setMessages(prev=>prev.some(x=>x._id===m._id)?prev:[...prev,m]);setConversations(prev=>prev.map(c=>c._id===activeConversation._id?{...c,lastMessage:m,updatedAt:m.createdAt,unreadCount:0}:c).sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)))}catch(e){setMessage(e.message)}};

  const openUser=async id=>{try{const d=await apiFetch("/api/users/"+id,auth);setViewUser(d);setConnections(null);setActive("user-profile");setQuery("");setSearchResults([])}catch(e){setMessage(e.message)}};
